package com.bank.logaudit;

import java.util.*;
import java.util.logging.*;

public class LogAuditDemo {
    private static final Logger log = Logger.getLogger("LogAudit");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        // Simulated /var/log/secure lines.
        List<String> authLog = List.of(
            "Oct 29 00:40:01 settlement sshd: Accepted publickey for ec2-user from 10.0.1.5",
            "Oct 29 00:41:10 settlement sshd: Failed password for invalid user admin from 203.0.113.9",
            "Oct 29 00:41:12 settlement sshd: Failed password for invalid user root from 203.0.113.9",
            "Oct 29 00:41:14 settlement sshd: Failed password for invalid user oracle from 203.0.113.9"
        );
        LoginAuditor auditor = new LoginAuditor();
        List<LoginEvent> events = auditor.parse(authLog);
        events.forEach(e -> log.info(e::toString));
        log.warning(() -> "Brute-force suspected from: " + auditor.bruteForceSources(events, 3));

        // Application log inspection by level.
        List<String> appLog = List.of(
            "INFO settlement started",
            "SEVERE settlement failed to reach NPCI",
            "INFO batch SETL-2026-10-29 completed");
        LogInspector inspector = new LogInspector();
        log.info(() -> "SEVERE lines: " + inspector.byLevel(appLog, "SEVERE"));
    }
}

// ─── Would be in LoginEvent.java ───
class LoginEvent {
    final boolean success; final String user; final String sourceIp;
    LoginEvent(boolean success, String user, String sourceIp) {
        this.success = success; this.user = user; this.sourceIp = sourceIp;
    }
    @Override public String toString() {
        return (success ? "LOGIN OK " : "LOGIN FAIL ") + user + " from " + sourceIp;
    }
}

// ─── Would be in LoginAuditor.java ───
class LoginAuditor {
    List<LoginEvent> parse(List<String> lines) {
        List<LoginEvent> out = new ArrayList<>();
        for (String l : lines) {
            boolean ok = l.contains("Accepted");
            boolean fail = l.contains("Failed");
            if (!ok && !fail) continue;
            String user = extractAfter(l, ok ? "for " : "user ");
            String ip = extractAfter(l, "from ");
            out.add(new LoginEvent(ok, user, ip));
        }
        return out;
    }
    // Sources with failed attempts at or above the threshold look like brute force.
    Set<String> bruteForceSources(List<LoginEvent> events, int threshold) {
        Map<String, Integer> fails = new HashMap<>();
        for (LoginEvent e : events)
            if (!e.success) fails.merge(e.sourceIp, 1, Integer::sum);
        Set<String> bad = new HashSet<>();
        fails.forEach((ip, n) -> { if (n >= threshold) bad.add(ip); });
        return bad;
    }
    private String extractAfter(String line, String token) {
        int i = line.indexOf(token);
        if (i < 0) return "?";
        String rest = line.substring(i + token.length());
        return rest.split("\\s+")[0];
    }
}

// ─── Would be in LogInspector.java ───
class LogInspector {
    List<String> byLevel(List<String> lines, String level) {
        return lines.stream().filter(l -> l.startsWith(level)).toList();
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), r.getMessage());
    }
}
